INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6b23b1d-4872-4de7-a8cf-51a523a7e494', 'ec3a760d-1098-4acd-9985-22683b3d88ec', 0, 'History and exam elements only, with medical decision making never a factor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63186d2f-5b0e-4455-ac56-aead6aa6394b', 'ec3a760d-1098-4acd-9985-22683b3d88ec', 1, 'Either the total time spent on the date of the encounter, or the level of medical decision making (MDM) — history and exam are no longer used as the primary leveling criteria for office/outpatient E/M codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9de3fc22-e3a4-44a2-a87f-485398aa90c7', 'ec3a760d-1098-4acd-9985-22683b3d88ec', 2, 'Only the number of body systems examined');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f662c218-0d06-4764-9426-611a4f782016', 'ec3a760d-1098-4acd-9985-22683b3d88ec', 3, 'Only the complexity of the presenting problem, unrelated to time or MDM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96561ba6-c540-4b60-98fc-be6a2c16220d', '190fe468-9dea-4fbd-b83f-f10197536b77', 0, 'The patient''s insurance type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2a998d4-603f-4d09-9468-9907652b0cd9', '190fe468-9dea-4fbd-b83f-f10197536b77', 1, 'Number and complexity of problems addressed at the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1b2632a-35d7-4275-b760-8a8ce259bab9', '190fe468-9dea-4fbd-b83f-f10197536b77', 2, 'The time of day the encounter occurred');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cb82bb4-456f-483c-8e39-ed78d7447458', '190fe468-9dea-4fbd-b83f-f10197536b77', 3, 'The specialty of the physician performing the service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7339801-0d37-469a-a827-bc60b82797f4', '4c0c1976-9396-4503-8c5f-56ec019c93b7', 0, 'Only time spent physically in the exam room with the patient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cb95db0-9533-4505-b06d-08125633ece9', '4c0c1976-9396-4503-8c5f-56ec019c93b7', 1, 'Both face-to-face and non-face-to-face time personally spent by the physician/qualified health professional on the date of the encounter (e.g., reviewing records beforehand, documenting, care coordination), not just direct face time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e36acac8-13d9-40c0-9502-cf4170e05c0a', '4c0c1976-9396-4503-8c5f-56ec019c93b7', 2, 'Time spent by clinical staff taking vital signs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fa5517d-3c46-4f3c-820f-733e107040b2', '4c0c1976-9396-4503-8c5f-56ec019c93b7', 3, 'Time spent by the patient in the waiting room');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df98b1d5-8c43-401d-873c-adafcbeddd12', '1fe139b2-628e-4062-9fc1-e45fc797d18a', 0, 'A patient who has never had any medical condition before');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf7c20bc-d511-4cc9-aad1-db946c7d2a70', '1fe139b2-628e-4062-9fc1-e45fc797d18a', 1, 'A patient who has not received any professional service from the physician or another physician of the exact same specialty and subspecialty in the same group practice within the past three years');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7aa1b6fd-7126-4f77-8967-48400c7ce531', '1fe139b2-628e-4062-9fc1-e45fc797d18a', 2, 'A patient under 18 years old');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de5aece0-5ee3-4278-bb1c-fd561fcd3a8d', '1fe139b2-628e-4062-9fc1-e45fc797d18a', 3, 'A patient who has changed insurance plans since their last visit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('632c3c71-3daa-468b-a89d-8dac1c819933', '96c36a9e-1610-4e2c-a7b2-c58e2908870c', 0, 'A rigid, mandatory checklist of body systems that must all be documented for every visit regardless of complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31aaace1-fd2e-4179-b158-382cf2ae0bba', '96c36a9e-1610-4e2c-a7b2-c58e2908870c', 1, 'History and exam should be performed and documented as clinically appropriate for the presenting problem, at the physician''s clinical judgment, since these elements no longer independently determine the code level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7d08792-06b6-4ffc-820a-2344592ede2c', '96c36a9e-1610-4e2c-a7b2-c58e2908870c', 2, 'History and exam documentation is now entirely optional and need never be performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be0c002e-bafc-4ae0-8a5a-e007b17b0187', '96c36a9e-1610-4e2c-a7b2-c58e2908870c', 3, 'History and exam are now scored using the same point system as MDM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3dac8da-5801-4925-ad4e-1bc016b8b908', '6d8d5a94-6848-4fc9-8e31-d99c9fe636d1', 0, 'A single, self-limited or minor problem requiring minimal management, minimal or no data review, and minimal risk of complications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e2b0f7a-9b3c-4622-8389-91500c65dcf9', '6d8d5a94-6848-4fc9-8e31-d99c9fe636d1', 1, 'Multiple chronic illnesses with severe exacerbation requiring urgent hospitalization');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('368464b8-ee2c-449d-a7b7-f4e5796f2441', '6d8d5a94-6848-4fc9-8e31-d99c9fe636d1', 2, 'A new problem with uncertain prognosis requiring extensive workup and high risk of morbidity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1aad309-44c9-4a1e-bf1f-5d58bf116f06', '6d8d5a94-6848-4fc9-8e31-d99c9fe636d1', 3, 'A chronic illness with severe side effects of treatment requiring intensive monitoring for toxicity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03c4350a-45cd-4e49-9d55-118e15dd5723', '1104ae83-0e45-4088-8db0-1cfcc2278aa2', 0, 'A request for the consulting physician''s opinion/advice from another physician or appropriate source, and a written report of findings/recommendations communicated back to the requesting party');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af6e8ecf-e9d9-4add-9283-d077c11aaec7', '1104ae83-0e45-4088-8db0-1cfcc2278aa2', 1, 'Only that the patient was seen by more than one physician during a hospital stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81f4a93b-c918-4c28-9d83-00fc523b41d0', '1104ae83-0e45-4088-8db0-1cfcc2278aa2', 2, 'Only that the consulting physician bills at a higher rate than the requesting physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('936c3e6f-3f06-4b62-a2aa-95d35d9ec3d8', '1104ae83-0e45-4088-8db0-1cfcc2278aa2', 3, 'Nothing beyond the visit note itself, with no communication back to the requester required');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc5ba0b2-5f54-4b66-ab0a-93655d9e5cb0', '8203b657-adc6-4ff9-a812-bbbb2f8ed860', 0, 'There is no coding distinction; both are billed identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('227289ba-5e36-4123-8578-a937a0d8eafb', '8203b657-adc6-4ff9-a812-bbbb2f8ed860', 1, 'Preventive medicine services use a distinct set of CPT codes based on patient age (not MDM/time) for a comprehensive, routine wellness-focused exam, while problem-oriented E/M codes address a specific complaint/condition and are leveled by MDM or time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66b75fce-ab9d-4258-aee5-8e6a15d2c07f', '8203b657-adc6-4ff9-a812-bbbb2f8ed860', 2, 'Problem-oriented visits are always billed at a higher level than preventive visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84e6c4a1-cf44-48a0-9d45-833eca8534dd', '8203b657-adc6-4ff9-a812-bbbb2f8ed860', 3, 'Preventive medicine codes are only used for pediatric patients');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9dd2dcc3-d757-417a-976f-15ca8560b436', '436d0c93-7a6c-468a-8171-87b8f1e20d03', 0, 'Reporting only the preventive medicine code, with the problem-oriented service never separately reportable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83ee2e18-9db0-4cb0-a11c-043f47f1926b', '436d0c93-7a6c-468a-8171-87b8f1e20d03', 1, 'Reporting both the preventive medicine code and the problem-oriented E/M code, with modifier 25 appended to the problem-oriented E/M code to indicate it was significant and separately identifiable from the preventive service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a61c58af-a6fa-48fc-bf39-ed4542f74627', '436d0c93-7a6c-468a-8171-87b8f1e20d03', 2, 'Reporting only the problem-oriented E/M code, dropping the preventive service entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2eb8013-f5fa-4f32-9ab2-39bb88e6cb23', '436d0c93-7a6c-468a-8171-87b8f1e20d03', 3, 'Billing the visit twice under two different patient accounts');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32b7438f-f2f4-445e-828a-8ce06b27d2c0', '07862ab5-e319-44e9-8308-6844e55b5098', 0, 'A completely separate encounter on a different date');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8e4680f-3b10-432a-8735-1708ffcf588b', '07862ab5-e319-44e9-8308-6844e55b5098', 1, 'Additional time spent by the physician beyond the typical time of the primary E/M service, when time is used as the basis for code selection and the additional time meets the threshold defined for the prolonged services code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('779b8ad3-1ea1-485c-91b9-43a7e31f158c', '07862ab5-e319-44e9-8308-6844e55b5098', 2, 'Time spent by ancillary/clinical staff instead of the physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a57fd835-e748-4118-8791-2d89e8209866', '07862ab5-e319-44e9-8308-6844e55b5098', 3, 'A higher level of medical decision making without any additional time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a5614e0-aa31-4641-9a7b-0a07eb95cc21', '5f01fb68-854d-4ced-9b38-ffbaf26a285a', 0, 'A code that can be billed as a stand-alone service with no primary procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d85941a6-6963-40f8-b891-dbd37d526bfa', '5f01fb68-854d-4ced-9b38-ffbaf26a285a', 1, 'A code reported only in addition to a specified primary procedure/service code, never independently, reflecting additional work performed during the same session as that primary service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('693b692d-afeb-4af5-acfa-532342591a53', '5f01fb68-854d-4ced-9b38-ffbaf26a285a', 2, 'A code used only for telehealth encounters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35f43601-f427-4999-8d70-c31b5f0e7db8', '5f01fb68-854d-4ced-9b38-ffbaf26a285a', 3, 'A code that always requires modifier 59');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4cae587-b046-40d8-8987-8390c2780a33', '225e24a9-615c-41fc-b169-1bc87e745e63', 0, 'The physician''s own diagnosis at the end of the visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31f3130d-66a9-45c8-a167-e8d69a0fa4dc', '225e24a9-615c-41fc-b169-1bc87e745e63', 1, 'A concise statement, typically in the patient''s own words, describing the symptom, problem, condition, or reason prompting the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('052b88a7-ca6c-48dc-b6bf-efd16520c21c', '225e24a9-615c-41fc-b169-1bc87e745e63', 2, 'The insurance billing code assigned to the visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a965fc7b-78f1-47a8-aab5-d203d925ce40', '225e24a9-615c-41fc-b169-1bc87e745e63', 3, 'The name of the referring physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc0f5782-81da-493c-b0ea-d4bc5ea9d7cf', '2123b173-d3e5-4d2a-a5ab-17223a061c95', 0, 'ED E/M codes distinguish new and established patients the same way office/outpatient codes do');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('670cbc30-3fee-4b9c-934f-190288247640', '2123b173-d3e5-4d2a-a5ab-17223a061c95', 1, 'ED E/M codes do not distinguish between new and established patients — the same code set applies regardless of whether the patient has been seen before by that group/specialty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1383c9b-15bd-4af8-92fc-98dd6206bad0', '2123b173-d3e5-4d2a-a5ab-17223a061c95', 2, 'ED E/M codes are leveled exclusively by time, never MDM');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48fff3be-6a79-4661-a6d6-3a1daa67d589', '2123b173-d3e5-4d2a-a5ab-17223a061c95', 3, 'ED visits can never be coded using E/M codes at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cf3b6c8-de8f-49d5-a6d1-5cd30e8c0459', 'e246e936-a1ec-47cb-8f33-2779105e7d6a', 0, 'Medical necessity is a marketing term with no coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb3cf010-2f79-4e95-a235-da09bc76025b', 'e246e936-a1ec-47cb-8f33-2779105e7d6a', 1, 'The overarching principle that the volume/level and type of services provided and coded should be reasonable and consistent with the patient''s clinical presentation and need for care — a higher-level code is not supportable simply because more work was documented if it wasn''t clinically necessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe8ff015-9a76-4058-b925-c5ee352dbc42', 'e246e936-a1ec-47cb-8f33-2779105e7d6a', 2, 'Medical necessity applies only to surgical procedures, never E/M visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b09b688-833b-4105-9e96-4509db21265b', 'e246e936-a1ec-47cb-8f33-2779105e7d6a', 3, 'Medical necessity is determined solely by the patient''s stated preference for a certain code level');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5ecfc91-2eb2-4ad7-8e79-61e56956c6a2', 'b4d1175e-e428-4824-b739-f02535563c7f', 0, 'The patient''s marital status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61ac7962-e85f-42ee-a3ef-96f6d91e996b', 'b4d1175e-e428-4824-b739-f02535563c7f', 1, 'Ordering and reviewing unique tests, reviewing prior external notes from another provider/organization, and independently interpreting a test performed by another physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ef1a012-6139-4ed1-a52a-5402947650df', 'b4d1175e-e428-4824-b739-f02535563c7f', 2, 'The number of years the physician has practiced medicine');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99410543-52c9-4142-968c-d46558a9a844', 'b4d1175e-e428-4824-b739-f02535563c7f', 3, 'The color-coding used in the EHR interface');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e240d0f-d098-4517-9abe-b38f257c3d77', '696bd637-29fa-4f09-b382-e2625a60ff48', 0, 'They are used for standard reimbursable procedures identical in function to Category I codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a455ab39-5960-4278-bafe-941448f64ab0', '696bd637-29fa-4f09-b382-e2625a60ff48', 1, 'They are optional, supplemental tracking codes used primarily for performance measurement and quality reporting purposes, and generally carry no relative value/reimbursement on their own');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a2422ec-d4d1-4988-9afc-d0f0e51fe569', '696bd637-29fa-4f09-b382-e2625a60ff48', 2, 'They represent emerging/experimental technology not yet approved for general use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8369c053-0031-4eea-8735-aa23d792a9fc', '696bd637-29fa-4f09-b382-e2625a60ff48', 3, 'They replace ICD-10-CM diagnosis codes entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f63fdd13-f451-42a7-9805-3279abffb8a8', '8d7d5803-2dbe-4e3f-b622-c19423cc7877', 0, 'Temporary codes for emerging technology, services, and procedures, used to track new/evolving services before enough data exists to support a permanent Category I code, if ever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09fe3474-bc66-41cf-a0a8-8fb8b6c1b138', '8d7d5803-2dbe-4e3f-b622-c19423cc7877', 1, 'Codes used exclusively for anesthesia services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70fcbe10-b2df-4273-a40d-93e1e4189529', '8d7d5803-2dbe-4e3f-b622-c19423cc7877', 2, 'Permanent codes for well-established, long-standing procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f096b0f-c481-4ef8-9f52-b9a8e599f367', '8d7d5803-2dbe-4e3f-b622-c19423cc7877', 3, 'Codes that replace HCPCS Level II codes entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1d9f86c-0cec-4891-b552-7b651c35d557', 'a168f0d4-2c44-4610-b904-2471bae70e11', 0, 'Ordering a test and independently interpreting it (beyond just reading a report already prepared by another physician) are treated identically for MDM data-complexity purposes, with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26693c37-0ecd-4039-9636-54464ee960cb', 'a168f0d4-2c44-4610-b904-2471bae70e11', 1, 'Independently interpreting a test (e.g., a physician personally reviewing and interpreting an EKG tracing rather than relying solely on the automated/another physician''s official report) reflects a distinct, higher level of data engagement than merely ordering the test or reading someone else''s final report');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4eecf2aa-e47b-467d-b101-627d618d93e9', 'a168f0d4-2c44-4610-b904-2471bae70e11', 2, 'Independent interpretation is never a factor in MDM under current guidelines');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('806e032c-2257-4823-b199-3347b3305d85', 'a168f0d4-2c44-4610-b904-2471bae70e11', 3, 'Only radiologists may ever receive credit for independent interpretation under E/M MDM rules');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ee766ec-b020-4117-bab1-8af2235e531c', 'c906df50-fea0-4c27-aedd-ae8d7b746545', 0, 'It considers only the risk inherent in the patient''s underlying diagnosis, never the risk of the chosen management/treatment approach itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ae43caf-d76b-499e-bdbb-0284ff1e3670', 'c906df50-fea0-4c27-aedd-ae8d7b746545', 1, 'It considers the risk associated with the management decisions made at that encounter — such as prescription drug management, decisions regarding hospitalization, or risk associated with social determinants of health — not merely the diagnosis''s inherent severity in isolation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a3b8866-ddbf-4779-ac86-f9bf96a80143', 'c906df50-fea0-4c27-aedd-ae8d7b746545', 2, 'It is determined solely by the patient''s age');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e73a082a-672a-4ec6-94c6-1ac88c660426', 'c906df50-fea0-4c27-aedd-ae8d7b746545', 3, 'It has been eliminated from current MDM guidelines entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58722417-f6f8-40cb-bb4c-8ac55877af03', '811b56c6-d22d-4712-8f94-13e6219dfbf7', 0, 'Typical visit complexity is an acceptable, routine basis for code selection, since payers expect consistent leveling by patient type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2fa561c4-72d7-4932-9b21-2142acdb116d', '811b56c6-d22d-4712-8f94-13e6219dfbf7', 1, 'Each individual encounter must be leveled on its own actual, specific documented complexity/time — using a physician''s ''typical'' pattern for a certain patient type as a shortcut, rather than the actual encounter''s documented facts, risks both under- and over-coding relative to what genuinely occurred that visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2093edf-eccd-4be5-9dab-b7720ca572a6', '811b56c6-d22d-4712-8f94-13e6219dfbf7', 2, 'E/M coding is always based on the patient''s diagnosis alone, never the encounter''s actual complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c7de2ee-be88-48c1-a638-dab9bd271657', '811b56c6-d22d-4712-8f94-13e6219dfbf7', 3, 'Only the first visit in a calendar year needs to reflect actual encounter-specific complexity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32aa5e7b-7e36-4920-ba2a-20797a547fa8', 'ad93be73-a7f5-4e26-a541-654022b9a343', 0, 'A flat fee identical for every anesthesia service regardless of complexity or duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03211ce5-707f-4dfd-b16e-9c8aa255a514', 'ad93be73-a7f5-4e26-a541-654022b9a343', 1, 'Base units (reflecting the complexity/typical difficulty of the specific procedure) plus time units (reflecting the actual duration of anesthesia care), often combined with a conversion factor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4e19f5d-1902-4eb7-95dc-0e586b326381', 'ad93be73-a7f5-4e26-a541-654022b9a343', 2, 'Only the anesthesiologist''s number of years in practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a81242de-77c0-48fa-a08f-0e1c79ee78d8', 'ad93be73-a7f5-4e26-a541-654022b9a343', 3, 'Only the total surgical facility''s overhead costs');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58ba7aa6-d351-49c1-9438-c4e5fafc63f1', '4efa9c8d-cb5a-4b55-a22d-d821706d6621', 0, 'The specific anesthesia technique used (general vs. regional)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('488ec3b7-835b-4840-9f41-b06d5ef06520', '4efa9c8d-cb5a-4b55-a22d-d821706d6621', 1, 'The patient''s overall physical condition/health status at the time of anesthesia, ranging from a normal healthy patient (P1) to a declared brain-dead patient whose organs are being removed for donation purposes (P6)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93630f26-55e8-40c0-86c5-1086f4bb55e6', '4efa9c8d-cb5a-4b55-a22d-d821706d6621', 2, 'The anesthesiologist''s board certification status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2b28914-a958-4eb1-9da8-af3de73fab81', '4efa9c8d-cb5a-4b55-a22d-d821706d6621', 3, 'The surgical facility''s accreditation level');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69b4e938-328a-43cb-bab3-a6a185956ada', '2341b999-7f92-411b-a4d2-99c0989b457f', 0, 'Routine, unremarkable anesthesia cases with no complicating factors');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a131bd9c-0b51-4421-b31e-b27f387b3352', '2341b999-7f92-411b-a4d2-99c0989b457f', 1, 'Circumstances that significantly complicate the administration of anesthesia (e.g., extreme patient age, total body hypothermia, controlled hypotension, or emergency conditions), reported as add-on codes alongside the primary anesthesia code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('069fde2e-0425-4582-8774-93c6b1756243', '2341b999-7f92-411b-a4d2-99c0989b457f', 2, 'The specific type of IV fluid administered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84ab3f29-41bc-4370-ac8c-3b947bf0d1e1', '2341b999-7f92-411b-a4d2-99c0989b457f', 3, 'The room number where the procedure was performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('462ba882-bf38-454a-9bb2-8041577ff3c0', 'd1ce42c8-46a2-43cc-b2b9-1d42aa24ee38', 0, 'MAC and general anesthesia are coded identically with no distinction ever made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77b0cabd-8f9f-4bc9-9836-cb75c77d49e8', 'd1ce42c8-46a2-43cc-b2b9-1d42aa24ee38', 1, 'MAC involves an anesthesia provider monitoring the patient and administering sedation/analgesia as needed, typically without inducing full unconsciousness as with general anesthesia, and has its own specific coding/modifier conventions (e.g., a MAC-specific modifier in some contexts)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7523f949-be7c-4cb4-b163-1c81db309d3d', 'd1ce42c8-46a2-43cc-b2b9-1d42aa24ee38', 2, 'MAC is used only for pediatric patients');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da12083b-970b-428f-b5ae-b93fd68bf1be', 'd1ce42c8-46a2-43cc-b2b9-1d42aa24ee38', 3, 'MAC always requires two anesthesiologists to be present simultaneously');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9830b112-952c-434f-ac07-ffb3033ebe07', '8df4cb42-6a0b-4683-a748-ea75f539485d', 0, 'Reporting the anesthesia code with the highest base unit value for the combined session, rather than billing each anesthesia service as if performed as entirely separate, sequential encounters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23ec770e-911b-4e53-a131-e84decc2c91c', '8df4cb42-6a0b-4683-a748-ea75f539485d', 1, 'Always billing both anesthesia codes at their full separate values with no combination logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b42ac167-8503-41fa-925e-9cb12193a1af', '8df4cb42-6a0b-4683-a748-ea75f539485d', 2, 'Never billing for anesthesia when multiple procedures occur in one session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f612585e-daf5-451f-b872-72aec70846d9', '8df4cb42-6a0b-4683-a748-ea75f539485d', 3, 'Billing only the lower-valued anesthesia code and ignoring the higher one');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56e9a8d0-c2a9-47ed-82e4-3b1a7345b9e7', 'de2774cc-74bf-4d6c-97c1-2a1183f68c0f', 0, 'The surgeon makes the first incision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d28011bb-b8a4-44dc-98b2-fe7c2167c67a', 'de2774cc-74bf-4d6c-97c1-2a1183f68c0f', 1, 'The anesthesiologist begins to prepare the patient for anesthesia care in the operating room (or comparable) setting and continues until the patient may be safely placed under postoperative supervision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb7999b9-49b2-40a0-898f-733e5e8c9693', 'de2774cc-74bf-4d6c-97c1-2a1183f68c0f', 2, 'The patient is discharged from the facility entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('536007ce-d273-4de5-96b2-3da6ef1d5962', 'de2774cc-74bf-4d6c-97c1-2a1183f68c0f', 3, 'The patient signs the surgical consent form');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0448e628-0a85-4589-a910-eda69c5f0533', 'b07dd18e-f3c4-4dbd-8f8c-3baa750f890d', 0, 'Usual preoperative and postoperative visits related to the anesthesia service, and administration of fluids/blood incidental to the anesthesia care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4dc0f4c5-a69b-4eff-bbdb-b312d3132a7e', 'b07dd18e-f3c4-4dbd-8f8c-3baa750f890d', 1, 'An entirely separate, unrelated surgical procedure performed by a different surgeon on a different day');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be666224-f7cf-4703-9113-babd2b41675a', 'b07dd18e-f3c4-4dbd-8f8c-3baa750f890d', 2, 'A qualifying circumstance add-on for an emergency case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27e5c789-bc28-449f-9acc-1103fcbf73f1', 'b07dd18e-f3c4-4dbd-8f8c-3baa750f890d', 3, 'Anesthesia services for a second, unrelated procedure performed weeks later');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bb70b4e-0ea5-4edb-95eb-ac0ea2169eda', 'b28af0d9-ce24-4cd5-b436-30a104ef650e', 0, 'Moderate sedation is always coded identically to general anesthesia with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12892496-2b52-4d0b-aa3b-9174dd05df10', 'b28af0d9-ce24-4cd5-b436-30a104ef650e', 1, 'CPT includes specific moderate sedation codes for when the physician performing a procedure (or another physician/qualified professional) personally provides and monitors sedation short of general anesthesia, distinct from anesthesia codes reported by a separate anesthesia provider for general anesthesia or MAC');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('874ce664-c5e1-41b7-8fb6-d316e992e68f', 'b28af0d9-ce24-4cd5-b436-30a104ef650e', 2, 'Moderate sedation may never be separately reported under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f473f2a4-5800-417d-9a60-f06cfd5bf555', 'b28af0d9-ce24-4cd5-b436-30a104ef650e', 3, 'Moderate sedation codes apply only to dental procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('876e355f-f5e9-493d-8eef-f280a55cb999', '58f37f51-15a2-4f58-9271-eb7e44e0de38', 0, 'A single universal anesthesia code applies to every procedure regardless of body area or complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91ed282f-922a-4a63-ab3e-14a3df77bc11', '58f37f51-15a2-4f58-9271-eb7e44e0de38', 1, 'Anesthesia codes are generally organized by anatomic region/type of procedure being supported (e.g., anesthesia for procedures on the upper abdomen, or for a specific joint), each carrying its own base unit value reflecting typical complexity for that category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('123de3ab-a836-463f-aa74-c82c15d860e1', '58f37f51-15a2-4f58-9271-eb7e44e0de38', 2, 'Anesthesia codes are selected based solely on the anesthesiologist''s preference with no relation to the procedure performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16da2abc-ad3d-4c1c-aa3e-3df59204950a', '58f37f51-15a2-4f58-9271-eb7e44e0de38', 3, 'Anesthesia code selection depends only on the total anesthesia time, never the type of procedure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77bc92f2-a748-4134-a9ab-4958b958d455', 'b39b1cff-abea-4ea5-b692-aad6df7593e6', 0, 'It is never appropriate to note or separately consider unusual circumstances requiring anesthesia beyond what''s typical for a given procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e846005b-d305-4f4e-bc4e-5e446ebebeb5', 'b39b1cff-abea-4ea5-b692-aad6df7593e6', 1, 'When a procedure that doesn''t typically require general anesthesia genuinely requires it due to unusual circumstances (e.g., a patient who cannot cooperate for a procedure normally done with local anesthesia alone), this circumstance should be documented and coded appropriately per the applicable modifier/coding convention for unusual anesthesia services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fca41f24-9761-4e15-9286-d7adde9b3a39', 'b39b1cff-abea-4ea5-b692-aad6df7593e6', 2, 'Unusual anesthesia circumstances are billed using the same code and modifier as a routine case with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67bf9b09-5e22-4a1b-a068-3aa8a4a13fd7', 'b39b1cff-abea-4ea5-b692-aad6df7593e6', 3, 'This scenario applies only to pediatric anesthesia, never adult patients');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('babda12a-a65c-471e-a9c3-c8ece9781a19', '60d2a475-a061-4117-b2a7-6261c5906be9', 0, 'An unrelated E/M visit for a new, distinct problem occurring during the postoperative period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c061e5a-b333-459f-bb4b-8533785d6ed2', '60d2a475-a061-4117-b2a7-6261c5906be9', 1, 'Uncomplicated postoperative care/follow-up visits related to the surgery, and local infiltration/topical/digital block anesthesia administered by the surgeon, within the defined global period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2af5327c-f7ce-4ed8-8131-d508329df7ea', '60d2a475-a061-4117-b2a7-6261c5906be9', 2, 'Treatment of a complication requiring a return trip to the operating room');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8aef21ce-51f9-4c73-9153-9711d6c78e54', '60d2a475-a061-4117-b2a7-6261c5906be9', 3, 'Services provided by a completely different specialist for an unrelated condition');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9639f869-6ad8-45c1-8f2d-8001265e89a0', 'c13f4c08-40ee-445f-8382-31c812c09d5b', 0, 'Modifier 24 (unrelated E/M service by the same physician during a postoperative period)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10c95841-71bd-48a5-806e-6bc122a1b188', 'c13f4c08-40ee-445f-8382-31c812c09d5b', 1, 'Modifier 51 (multiple procedures)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1909dd5a-6828-4a3e-b385-c7a2ab4e078a', 'c13f4c08-40ee-445f-8382-31c812c09d5b', 2, 'Modifier 62 (two surgeons)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('418716d4-5252-484e-b8f0-d7e1fb7220e8', 'c13f4c08-40ee-445f-8382-31c812c09d5b', 3, 'Modifier 80 (assistant surgeon)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20836ee9-4f10-4e0f-bd4c-92e28fcb6ea0', 'f8a07707-b3c4-4e50-9860-b7ac704baf3a', 0, 'Modifier 78 (unplanned return to the operating/procedure room by the same physician for a related procedure during the postoperative period)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b05fbbc-f919-40f0-b4ca-45e9a6fabbec', 'f8a07707-b3c4-4e50-9860-b7ac704baf3a', 1, 'Modifier 59 (distinct procedural service)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77d1530d-b720-4ae0-80aa-9cd4de8c5c8a', 'f8a07707-b3c4-4e50-9860-b7ac704baf3a', 2, 'Modifier 22 (increased procedural services)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('985e810d-aa3f-4337-a276-278d182f5338', 'f8a07707-b3c4-4e50-9860-b7ac704baf3a', 3, 'Modifier 52 (reduced services)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c59d1e8-9b68-40b0-b151-063ac7c78629', '37122886-625a-47a9-9238-319e3a55af69', 0, 'Modifier 79');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5036ba2-8d23-41cd-99b7-6d376bf271d0', '37122886-625a-47a9-9238-319e3a55af69', 1, 'Modifier 78');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97d200a7-6e85-45c0-b2a8-1e2bfbba3163', '37122886-625a-47a9-9238-319e3a55af69', 2, 'Modifier 76');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('274ce582-715b-4176-b68e-ffb5bf22bc1f', '37122886-625a-47a9-9238-319e3a55af69', 3, 'Modifier 58');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c4e9aea-2c1b-433d-a2ed-afb8c7258b97', '53bc6c93-6b2e-4f4b-adc4-3c55b87d51b7', 0, 'Modifier 58 (staged or related procedure or service by the same physician during the postoperative period)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9777ecea-c142-4af2-b9f1-7cb11b2f8935', '53bc6c93-6b2e-4f4b-adc4-3c55b87d51b7', 1, 'Modifier 25');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cf10528-b21e-49e5-bba9-48968197b30f', '53bc6c93-6b2e-4f4b-adc4-3c55b87d51b7', 2, 'Modifier 57');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86c3421c-9a94-42e5-b3ee-d3015206d31f', '53bc6c93-6b2e-4f4b-adc4-3c55b87d51b7', 3, 'Modifier 91');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4315b936-682f-455f-9a9f-783cfd22befe', '783c2854-14f0-4636-9a96-b776ac3f1677', 0, 'The procedure must always be billed separately no matter what else was performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d1a9d37-1603-489b-b561-994d62793ded', '783c2854-14f0-4636-9a96-b776ac3f1677', 1, 'The procedure is typically considered a component of a larger, more comprehensive procedure and is not separately reportable when performed as an integral part of that larger procedure at the same session — but may be separately reportable if performed independently, unrelated to another procedure, or as a distinct, unrelated procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('469605c7-83d0-4b7e-bb9d-efe408d96b0d', '783c2854-14f0-4636-9a96-b776ac3f1677', 2, 'The procedure can never be billed under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2832ef19-faef-4ca9-8d63-c875cf1978eb', '783c2854-14f0-4636-9a96-b776ac3f1677', 3, 'The designation has no coding significance today');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6482a4c6-41f5-4cae-8cc4-8c61fc66420a', 'd833c376-d967-467f-9a71-4b4b577cd576', 0, 'Reporting every possible component of a procedure as a separate line item to maximize reimbursement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ad68824-7655-46d6-90ff-411e2a832504', 'd833c376-d967-467f-9a71-4b4b577cd576', 1, 'Certain component services/supplies integral to performing a more comprehensive procedure are considered part of that procedure''s single code and are not separately reportable, reflecting the CPT code descriptor''s own inherent scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96c61ac2-253f-4aac-8762-093cf1c066e4', 'd833c376-d967-467f-9a71-4b4b577cd576', 2, 'Bundling applies only to anesthesia codes, never surgical codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6d92e37-ea92-4fe2-b554-39b6aa17092f', 'd833c376-d967-467f-9a71-4b4b577cd576', 3, 'Bundling means combining two unrelated patients'' procedures into one claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4796bf70-d2c1-4dc5-86a1-5e49dd9b4503', '9ada821a-d693-4c62-be05-6b921971b833', 0, 'Two surgeons of different specialties each perform a distinct part of a single procedure as primary surgeons (not as surgeon/assistant), each reporting the same procedure code with modifier 62 appended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('988f8f7c-9995-4392-81ac-805fdb3f4a1e', '9ada821a-d693-4c62-be05-6b921971b833', 1, 'Any time more than one physician is present in the operating room for any reason');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2318b34d-be38-4a6a-a353-b4262f7f50f3', '9ada821a-d693-4c62-be05-6b921971b833', 2, 'A surgeon and an anesthesiologist work together on the same case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6242e95-e820-495e-acb2-52f3a6ed5797', '9ada821a-d693-4c62-be05-6b921971b833', 3, 'A resident physician assists a supervising attending surgeon');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7608d790-239f-4ebf-a90d-fe67cdb8855a', '034f4ecd-3647-45ea-af48-e7ce8840125b', 0, 'Modifier 80 (assistant surgeon)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ebb8dae-732e-4420-b4bf-cb54879d898f', '034f4ecd-3647-45ea-af48-e7ce8840125b', 1, 'Modifier 62 (two surgeons)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c540d2e-fdfe-476d-93d4-341562f370fa', '034f4ecd-3647-45ea-af48-e7ce8840125b', 2, 'Modifier 66 (surgical team)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84f98af2-6e16-400f-a392-31d1a4e2a07c', '034f4ecd-3647-45ea-af48-e7ce8840125b', 3, 'Modifier 78');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d924f0e-5147-43b0-a3dc-464097b2c34b', 'c6127e6e-1ade-4ca3-ab53-11b3deb4aa93', 0, 'Supplies/trays are always separately billable in addition to every procedure with no restrictions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d4916b4-c925-4a99-9cca-fd7dd104e705', 'c6127e6e-1ade-4ca3-ab53-11b3deb4aa93', 1, 'Basic supplies integral to performing a procedure are generally considered part of the procedure''s global package and not separately reportable, though certain distinct, itemizable supplies may sometimes be separately reportable depending on payer policy and HCPCS Level II supply codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8408ff22-82ad-454a-a34e-5c60bb2df9dd', 'c6127e6e-1ade-4ca3-ab53-11b3deb4aa93', 2, 'Supply codes replace the need for a CPT procedure code entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46246578-c3b1-43a9-87e6-c2cbe03fb654', 'c6127e6e-1ade-4ca3-ab53-11b3deb4aa93', 3, 'Supplies are billed only when the procedure is performed in an inpatient hospital setting');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('882e2c70-dc18-47c3-aaff-0fecb97f6c18', 'a27cae26-4008-44c1-bdfa-ad77a9922969', 0, 'Used routinely on every procedure to increase reimbursement regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2015381-2a7f-4087-8c73-0d4969b93162', 'a27cae26-4008-44c1-bdfa-ad77a9922969', 1, 'Used when the work required to provide a service is substantially greater than typically required, which must be clearly documented (e.g., significant additional time, increased complexity, unusual findings)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8c543c2-a7b1-454c-b07a-314d01e1ce7e', 'a27cae26-4008-44c1-bdfa-ad77a9922969', 2, 'Used exclusively for bilateral procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f101d5aa-8886-4692-9970-17dace74661a', 'a27cae26-4008-44c1-bdfa-ad77a9922969', 3, 'Used to indicate a procedure was performed by a resident physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55579065-59b2-4678-b09c-8a06262df2c3', 'dce3b8e5-d535-474d-affe-b357f6069a91', 0, 'Used when a service/procedure is partially reduced or eliminated at the physician''s discretion, reported to indicate the service was less extensive than the code descriptor typically represents, without a separate code existing for the reduced level of service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d8d7416-aac5-406a-be13-193c212666a4', 'dce3b8e5-d535-474d-affe-b357f6069a91', 1, 'Used when a procedure takes less time than average but is otherwise fully performed as described');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0908978f-39aa-4690-8033-404f21f2cc9a', 'dce3b8e5-d535-474d-affe-b357f6069a91', 2, 'Used only for anesthesia services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b01638e-8246-471b-be85-a8d5e5aef053', 'dce3b8e5-d535-474d-affe-b357f6069a91', 3, 'Used interchangeably with modifier 53 (discontinued procedure) with no distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2587432-750c-409b-8aba-c0dd0b7d45f7', 'f9b21ed8-a984-435d-a718-908cff07d27c', 0, 'Modifier 53 (discontinued procedure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66978525-8d41-4bdb-93b2-99423c402d3e', 'f9b21ed8-a984-435d-a718-908cff07d27c', 1, 'Modifier 52 (reduced services)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3c4aea8-17f8-4a46-a877-dd8f053e28dc', 'f9b21ed8-a984-435d-a718-908cff07d27c', 2, 'Modifier 73');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13642c6f-290d-4ec4-810d-ae0639b75654', 'f9b21ed8-a984-435d-a718-908cff07d27c', 3, 'Modifier 74');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6aa943e-4a05-4add-9f82-f30d12916dc1', '8c5423d7-ee33-4ae2-b33b-de9ba0e3d4e3', 0, 'The same code reported twice on two entirely separate claims filed weeks apart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb15d4bf-9e5c-4fe5-9290-7091bc2bfa54', '8c5423d7-ee33-4ae2-b33b-de9ba0e3d4e3', 1, 'Modifier 50 (bilateral procedure) appended to the single code to indicate the identical procedure was performed on both sides of the body during the same operative session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33d532e8-553a-4fc6-89ca-b958d654d077', '8c5423d7-ee33-4ae2-b33b-de9ba0e3d4e3', 2, 'A completely unrelated, separate CPT code exists for every possible bilateral variant of every procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('548afb08-d48a-4eb6-9ff8-f6bcc04a10cf', '8c5423d7-ee33-4ae2-b33b-de9ba0e3d4e3', 3, 'Bilateral procedures can never be reported using modifiers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50e34719-9a6b-4cd0-8d75-883c4e87f5e0', '1643edb9-5091-4dff-973f-ea9c8a36aee2', 0, 'Modifier 51 (multiple procedures)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b98c33f5-c5e8-4e79-b82e-9eaa7fef5fb4', '1643edb9-5091-4dff-973f-ea9c8a36aee2', 1, 'Modifier 25');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('639556fb-ecb1-4b0b-b299-3e512cc4e40f', '1643edb9-5091-4dff-973f-ea9c8a36aee2', 2, 'Modifier 24');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0beca34d-e9d5-409d-8e6c-9a6a6495f561', '1643edb9-5091-4dff-973f-ea9c8a36aee2', 3, 'Modifier 62');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5be34941-7b54-4a6d-aa6e-96d7f98f08a2', '5cbfda40-98ee-4db2-a28d-0d28563e973a', 0, 'They serve identical, interchangeable purposes with no practical distinction ever recommended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('284f3fd2-2ee6-4eb0-a32a-cb238da90e43', '5cbfda40-98ee-4db2-a28d-0d28563e973a', 1, 'Modifier 59 is a broader, less specific ''distinct procedural service'' modifier, while the X{EPSU} modifiers were introduced by CMS to provide more granular specificity (separate encounter, separate structure, separate practitioner, unusual non-overlapping service) — CMS guidance generally encourages using the more specific X-modifier when applicable rather than the general modifier 59');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e61b5a3c-822a-49d2-aef6-a9c97a1b0447', '5cbfda40-98ee-4db2-a28d-0d28563e973a', 2, 'X{EPSU} modifiers apply only to anesthesia claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('350de4c4-c387-4094-b34a-3b92c20a3d09', '5cbfda40-98ee-4db2-a28d-0d28563e973a', 3, 'Modifier 59 was completely retired and can no longer be used under any circumstances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a40f7f3-4eeb-410f-9df2-ac14964a9924', '3f0be64b-741a-442b-8698-e48b2a1cb8eb', 0, 'Applying it routinely to bypass any NCCI edit regardless of whether the services were actually clinically distinct');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7854a2a-1395-4238-87a8-7bd2dfa4bf99', '3f0be64b-741a-442b-8698-e48b2a1cb8eb', 1, 'Applying it only when the two services truly represent a distinct procedure/service, not normally reported together, that is clinically appropriate to separately report on that specific date (e.g., a different session, different anatomic site, or different procedure) — not to simply override a bundling edit for services that were genuinely part of the same procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bad2397d-9938-4504-9984-e9b1c27d09d0', '3f0be64b-741a-442b-8698-e48b2a1cb8eb', 2, 'Applying it only to Category III codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f422145-1e9c-47b5-9212-db153167368f', '3f0be64b-741a-442b-8698-e48b2a1cb8eb', 3, 'Applying it exclusively to modifier-51-eligible procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21610f95-4785-4312-9120-f6a185860407', '6bed366a-6794-4ac3-a958-0eee3f95b8cc', 0, 'A code used for the most common, routine procedures performed daily');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92983329-8cbf-4a2a-a8cb-baf8002a6c6b', '6bed366a-6794-4ac3-a958-0eee3f95b8cc', 1, 'A code used to report a procedure or service for which no specific CPT code exists, generally requiring a special report describing the nature/extent of the service to support the claim');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8d9a822-c4fe-4c60-8986-97942e990802', '6bed366a-6794-4ac3-a958-0eee3f95b8cc', 2, 'A code that automatically pays at the highest fee schedule rate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab55395c-7ea3-4d22-904f-bcbc1e3375a7', '6bed366a-6794-4ac3-a958-0eee3f95b8cc', 3, 'A code used only for cosmetic procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9a89b05-6265-41fb-b666-cb21b3567873', '3779c5d0-d839-442a-b4c9-deab66ef7fe4', 0, 'Both the diagnostic endoscopy and the open procedure are always billed in full, with no bundling consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f0df236-6fd1-4783-acf5-8aab8510abef', '3779c5d0-d839-442a-b4c9-deab66ef7fe4', 1, 'The diagnostic endoscopy is generally considered part of (bundled into) the more extensive open procedure it led directly into during the same session, and is not separately reportable, since the open approach superseded the need for the endoscopy as a standalone service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('334aebf6-48b2-4e75-80ad-d7cca0208ef2', '3779c5d0-d839-442a-b4c9-deab66ef7fe4', 2, 'Only the diagnostic endoscopy may be billed; the open procedure is never separately reportable in this scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4d13d8c-ada5-40b8-8251-d695172a12e0', '3779c5d0-d839-442a-b4c9-deab66ef7fe4', 3, 'The two procedures must always be billed under two different providers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4ef5cfc-9e11-452b-9b1c-2c516f1a5eca', '024040d5-79cb-4dbf-babb-ed60afc1c2e3', 0, 'Modifier 50 (bilateral)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('612844f2-0421-495e-b857-baf3d7644711', '024040d5-79cb-4dbf-babb-ed60afc1c2e3', 1, 'An anatomic modifier such as LT (left side) or RT (right side), used to indicate laterality on a unilateral procedure rather than modifier 50, which is specifically for the identical procedure performed bilaterally at the same session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da007628-e94c-4a4a-9043-84f51176b82c', '024040d5-79cb-4dbf-babb-ed60afc1c2e3', 2, 'Modifier 51 (multiple procedures)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('603c24c0-5e9b-4d25-bba5-ab31dd7884f7', '024040d5-79cb-4dbf-babb-ed60afc1c2e3', 3, 'Modifier 22 (increased procedural services)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bea52cb2-9558-4ffc-b8df-07aceee73574', '55b30400-aff1-4471-a7c3-bd1497c9211d', 0, 'The two modifiers serve identical purposes and are always interchangeable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a41eec1d-1a7c-4b69-8ea9-e9ce5b7ca18d', '55b30400-aff1-4471-a7c3-bd1497c9211d', 1, 'Modifier 51 generally signals multiple procedures for payment-adjustment purposes (when the payer requires it), while modifier 59 (or an X{EPSU} modifier) specifically addresses whether a code pair that might otherwise be bundled/edited together should be recognized as distinct — a procedure can potentially need one, both, or neither modifier depending on the specific code combination and payer edit logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b0f82aa-d761-4c98-a1d7-26fab9dd646b', '55b30400-aff1-4471-a7c3-bd1497c9211d', 2, 'Modifier 59 should always be applied to every procedure after the first, regardless of whether an NCCI edit exists for that pair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b09266b-de34-4ffc-949a-d4c893f97322', '55b30400-aff1-4471-a7c3-bd1497c9211d', 3, 'Modifier 51 is used only for anesthesia, never surgery');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21d2f12d-9b9d-4971-8839-0857b2cfb174', 'ed1f51a7-5535-4d4e-b92f-851d48f96b5e', 0, 'Simple, routine wound closure directly following a lesion excision is generally considered part of the excision code''s global package and not separately reportable, while a more complex/extensive repair technique beyond simple closure may be separately reportable using the appropriate repair code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4efd032d-3484-4c89-b342-1559caeccaa3', 'ed1f51a7-5535-4d4e-b92f-851d48f96b5e', 1, 'All wound closures following any excision are always separately billable in full, regardless of complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c45bd4ea-afae-4c08-be24-4d6489f3c2a4', 'ed1f51a7-5535-4d4e-b92f-851d48f96b5e', 2, 'Excision codes never include any closure at all, so closure must always be separately coded regardless of complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a746d2c8-7b8c-4360-a247-e5f1dfebfa05', 'ed1f51a7-5535-4d4e-b92f-851d48f96b5e', 3, 'Closure complexity has no bearing on whether it may be separately coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ceff9103-57d4-4e82-bf51-00c26b277cf5', '7f90f181-0a43-4ba5-b611-2d9b1dacbf02', 0, 'It is always separately billable in full regardless of clinical indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97e7ed29-d07a-4d0c-864e-de143badebf8', '7f90f181-0a43-4ba5-b611-2d9b1dacbf02', 1, 'An incidental procedure performed on a structure that was not diseased and not the primary indication for surgery is generally not separately reportable, since it doesn''t represent additional distinct, medically necessary surgical work beyond what the primary procedure already required access to');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7658e2ee-ab89-48a9-90df-f247602d1f29', '7f90f181-0a43-4ba5-b611-2d9b1dacbf02', 2, 'Incidental procedures must always be reported as the primary procedure instead of the actual indicated surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7eed148-a30a-4e4a-b968-93adf9db1d86', '7f90f181-0a43-4ba5-b611-2d9b1dacbf02', 3, 'Incidental procedures require a physician''s personal guarantee of payment before being coded at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fcb3fad2-f5b3-490f-8dae-0e9d2a9ca322', '049cf173-f2e9-4080-a8f2-51bfd8c1a1ec', 0, 'The repair of an intraoperative complication caused by, and repaired during, the same operative session as the original procedure is generally considered part of that procedure and not separately reportable, absent specific documentation/coding guidance indicating otherwise');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06ecfb04-b144-4e74-8305-13ebf7f9ab17', '049cf173-f2e9-4080-a8f2-51bfd8c1a1ec', 1, 'Every intraoperative complication repair is automatically separately billable using an unrelated-procedure modifier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d935a619-caa0-4a07-996c-29586417a66f', '049cf173-f2e9-4080-a8f2-51bfd8c1a1ec', 2, 'Intraoperative complications can never be documented or discussed in coding contexts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db116546-bcea-4e46-9af9-aa38199a9425', '049cf173-f2e9-4080-a8f2-51bfd8c1a1ec', 3, 'The complication repair is always billed as a completely separate encounter on a different claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1a55067-3a4b-469e-a1cd-f630bc039c9f', '0d3277fe-299c-4053-8530-91f68a3d57ee', 0, 'Component/comprehensive relationships exist only because of NCCI; without NCCI, no such relationship would ever exist in CPT''s own code structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1b6e2c8-46d2-4f86-ab08-530cfb52cf9c', '0d3277fe-299c-4053-8530-91f68a3d57ee', 1, 'Certain CPT code descriptors are inherently structured such that a more extensive code already includes the work of a less extensive, related code performed as part of the same procedure — this reflects the code descriptors'' own inherent scope and predates/exists independently of any specific NCCI edit built to enforce it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('892a936b-42e5-44ef-956d-b9532d2f11ce', '0d3277fe-299c-4053-8530-91f68a3d57ee', 2, 'Component/comprehensive relationships apply only to laboratory panel codes, never surgical codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db00231a-ea3c-467f-b9c6-79466d14e82e', '0d3277fe-299c-4053-8530-91f68a3d57ee', 3, 'There is no such thing as inherent code-descriptor bundling in CPT; all bundling is purely an NCCI creation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('945b4b4d-05c2-428b-8149-b8f035148b0e', 'a3ccfeae-6667-46c6-8fa7-b9fdc282b35f', 0, 'The staged procedure is never separately reportable under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('458f940e-bba4-4b33-b146-b807fe6fe0fa', 'a3ccfeae-6667-46c6-8fa7-b9fdc282b35f', 1, 'The staged procedure is generally separately reportable using modifier 58 (staged/related procedure by the same physician during the postoperative period), since it was planned/anticipated and represents a distinct, additional procedure rather than routine postoperative care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57c676be-eb6e-4f41-9479-c83c35e2cf48', 'a3ccfeae-6667-46c6-8fa7-b9fdc282b35f', 2, 'The staged procedure must always be performed by a different physician to be billed at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c4c0315-3662-44e9-80a9-27e64f723010', 'a3ccfeae-6667-46c6-8fa7-b9fdc282b35f', 3, 'Staged procedures are billed using modifier 78 instead of modifier 58');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03a84e0d-794a-4f84-9bd1-0bd4f86d37c2', '450dde5a-7bde-4f5d-9ecd-298eef5e092d', 0, 'The diagnostic biopsy and the more extensive therapeutic procedure are always both fully, separately billable with no bundling consideration whatsoever, regardless of relationship');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c03eb7e-277a-4f3c-b1bb-2f38cba98c5d', '450dde5a-7bde-4f5d-9ecd-298eef5e092d', 1, 'Coding guidance/payer policy in this scenario often depends on the specific codes/edits involved and documentation of medical necessity for both distinct steps — this is a genuinely nuanced area where coders must check specific code relationships/edits rather than applying a single blanket rule either way');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a31b38b-2a18-4dd0-94b9-03be46f8fdaa', '450dde5a-7bde-4f5d-9ecd-298eef5e092d', 2, 'The therapeutic procedure is never billable if a biopsy was performed at the same session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('151e7310-59a9-40a3-a24a-513fc0c47378', '450dde5a-7bde-4f5d-9ecd-298eef5e092d', 3, 'Only the biopsy may ever be billed in this scenario');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f31c0d69-1053-485d-8ed8-c76bc8a272e4', 'e93053ae-3d9c-4675-bb7f-08eab51d3f6b', 0, 'Add-on codes in Surgery represent entirely separate, unrelated procedures with no connection to a primary code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a5a00da-4db5-4c53-bf6b-c3e3f76d52c3', 'e93053ae-3d9c-4675-bb7f-08eab51d3f6b', 1, 'Surgery-section add-on codes typically capture incremental additional work (e.g., each additional lesion, level, or unit beyond a base/first occurrence) performed during the same session as, and reported alongside, an eligible primary procedure code — never billed as a stand-alone code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4432709b-d57e-44fd-afc1-7663e3947f68', 'e93053ae-3d9c-4675-bb7f-08eab51d3f6b', 2, 'Add-on codes in Surgery are used exclusively for bilateral procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdb726bf-4a95-4730-80a6-f43587eeeacf', 'e93053ae-3d9c-4675-bb7f-08eab51d3f6b', 3, 'Surgery add-on codes are billed at a higher rate than the primary procedure they accompany');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bfb6099-59df-4e8d-9efc-95b1f754aa34', '4f5d100c-8f79-4ef8-876d-f315ba220292', 0, 'Laterality/site specificity matters only for diagnosis coding, never for procedure coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03dc7cde-b6a1-487e-8956-8839ac148d0b', '4f5d100c-8f79-4ef8-876d-f315ba220292', 1, 'Procedure coding often requires the same anatomic-site specificity as diagnosis coding — anatomic modifiers (LT/RT, finger/toe modifiers, spinal level add-on codes) and code selection itself can depend on precisely which site/side was involved, making incomplete operative documentation of site/laterality a real coding-accuracy risk for procedures too, not just diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c8a091d-0d9b-44c9-8b9e-e1ac644b6569', '4f5d100c-8f79-4ef8-876d-f315ba220292', 2, 'Surgical coding never requires laterality specification under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7578a340-2e56-4ef3-9b04-08df054bb9d0', '4f5d100c-8f79-4ef8-876d-f315ba220292', 3, 'Only bilateral procedures ever require laterality documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19c3bb3e-fb1c-463d-a591-6a93ee3462b3', '8e42ab76-21e8-46db-96ce-767347d5cf69', 0, 'Both the laparoscopic approach code and the open approach code are always reported together in full');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79dd0743-f3f3-4b0f-b515-e62c616e96e0', '8e42ab76-21e8-46db-96ce-767347d5cf69', 1, 'Generally, only the code for the approach actually completed (the open procedure) is reported — the abandoned laparoscopic attempt is not separately coded, mirroring the same ''code what was actually completed'' principle used in ICD-10-PCS for converted procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6280b390-1110-495b-bb0c-624141c5b549', '8e42ab76-21e8-46db-96ce-767347d5cf69', 2, 'Only the laparoscopic code is reported, regardless of conversion to open');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f48d81c9-6074-4d4e-9a5c-655705e84a1d', '8e42ab76-21e8-46db-96ce-767347d5cf69', 3, 'A completely different, unrelated ''conversion'' code family is always used instead of either approach''s code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cc4b201-2c39-4f3d-b461-7bf9d64372e9', 'be857da1-0a3c-4bc9-8e03-0be42f1c7813', 0, 'Two entirely unrelated, separately billed procedures with no connection to each other');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1ab0a37-6a9e-452b-b425-b81103d0cd91', 'be857da1-0a3c-4bc9-8e03-0be42f1c7813', 1, 'The professional component reflects the physician''s work in supervising/interpreting the study and producing a report, while the technical component reflects the equipment, technologist labor, and facility costs of actually performing/acquiring the imaging — together they make up the ''global'' service when performed by the same entity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86ce7a71-ba0c-4acb-9059-e9eb5e23e9e6', 'be857da1-0a3c-4bc9-8e03-0be42f1c7813', 2, 'Modifier 26 is used only for surgical procedures, never imaging');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33d49ecc-38b2-4333-9dd0-ae4153028f48', 'be857da1-0a3c-4bc9-8e03-0be42f1c7813', 3, 'TC and 26 are interchangeable and may be used for the same claim line without distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5dedeb8-9014-4846-a706-844d6275a974', 'b5648b7d-ea14-4c5f-a6fa-5ef667c728a8', 0, 'Reporting only the professional component code, ignoring the technical component entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cef56704-ee49-48c4-985a-5b96b0dd1027', 'b5648b7d-ea14-4c5f-a6fa-5ef667c728a8', 1, 'Reporting the ''global'' radiology code (no modifier), which represents both the professional and technical components combined, since both were provided by the same entity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0824c762-c9ee-4f1e-bb6a-6bfd2e2c76bb', 'b5648b7d-ea14-4c5f-a6fa-5ef667c728a8', 2, 'Reporting the code twice, once with modifier 26 and once with modifier TC, from the same billing entity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0281c06f-c77f-4a5e-a03a-2a3e350f66fa', 'b5648b7d-ea14-4c5f-a6fa-5ef667c728a8', 3, 'Radiology services can never be billed globally under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a842fe7f-0499-4b27-a2aa-94be506119fd', '89c35b07-a8f4-4872-bc48-59344c04bc42', 0, 'The patient''s copayment amount exclusively, with no bearing on code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b1e7fe6-a031-4dd2-9dfb-41bf2fa229e9', '89c35b07-a8f4-4872-bc48-59344c04bc42', 1, 'Which specific CPT code is selected for the imaging study, since contrast use (or its absence, or a combination) is often a defining descriptor element distinguishing otherwise similar radiology codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c97418b7-8190-4fa6-968c-24e1c5955d6e', '89c35b07-a8f4-4872-bc48-59344c04bc42', 2, 'Nothing; contrast use has no coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46710155-72b2-4d40-b4b1-f217806fa2b9', '89c35b07-a8f4-4872-bc48-59344c04bc42', 3, 'Only whether a modifier is needed, never the base code itself');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96153c15-d5e3-4a09-a384-3b7c6fb62dc1', 'c75c4056-b310-4f74-a95e-dd6c0dc58f74', 0, 'Both physicians may bill the professional component code separately for the same study');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e35bcd15-2d1e-463c-8365-b7e6263d4610', 'c75c4056-b310-4f74-a95e-dd6c0dc58f74', 1, 'Generally, only the radiologist providing the official interpretation/report bills the professional component for that specific study; an ordering physician''s informal review as part of managing the patient is not separately billable as a distinct professional-component interpretation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53c3a0a6-8636-445a-bb7e-17a08d01b37a', 'c75c4056-b310-4f74-a95e-dd6c0dc58f74', 2, 'The ordering physician always has priority to bill regardless of who performed the official interpretation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb2c9996-fa26-48fe-a54a-a75ab58edf08', 'c75c4056-b310-4f74-a95e-dd6c0dc58f74', 3, 'Professional component billing depends solely on which physician saw the patient first');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a586dc41-d313-4d97-ae6d-7abed51fc85d', 'c7489c2b-e370-45b1-8984-3f1766dc73d7', 0, 'Number of views has no bearing on code selection; it''s purely documentation trivia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f172bda-3c1c-42b6-87db-9c273c36fa6f', 'c7489c2b-e370-45b1-8984-3f1766dc73d7', 1, 'The number of views/images obtained is frequently a defining code-selection criterion within the radiology code descriptor itself, meaning the same anatomic study performed with a different number of views may map to an entirely different CPT code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60d3912c-775f-43e0-abae-43120337ff23', 'c7489c2b-e370-45b1-8984-3f1766dc73d7', 2, 'View count only matters for billing purposes in veterinary radiology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b49f52e1-9654-4832-874d-eb7b1ee0b6f7', 'c7489c2b-e370-45b1-8984-3f1766dc73d7', 3, 'All radiology codes for a given body part share the exact same view-count requirement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe9bc4b8-b5bd-4f52-bb28-c431c8365fca', '316abaa6-e2f6-4da1-a4be-bc02657b80ca', 0, 'Appending it any time a radiologist is employed by the hospital, regardless of who owns the imaging equipment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a517f46-969b-4ab2-98fe-0c87245d64b1', '316abaa6-e2f6-4da1-a4be-bc02657b80ca', 1, 'Appending it when the radiologist performs only the professional interpretation/report component of a study, while a separate entity (e.g., the hospital) owns the equipment and bills the technical component separately');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87fab5ef-13ee-42cc-ad5c-2ef06e5bc1e9', '316abaa6-e2f6-4da1-a4be-bc02657b80ca', 2, 'Appending it to indicate a study was repeated due to poor image quality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5df53729-278e-47f7-94b7-39664fdd51a3', '316abaa6-e2f6-4da1-a4be-bc02657b80ca', 3, 'Appending it exclusively to ultrasound studies');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb64b77a-92f9-458a-ae9a-81ac1dd3835c', '6d08ddce-67f1-4007-9683-4248b8faa3e7', 0, 'The S&I code and the procedural code are always mutually exclusive and can never both be reported for the same encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('701ad449-0caf-4a7a-97ae-d2bc5c164f16', '6d08ddce-67f1-4007-9683-4248b8faa3e7', 1, 'Certain image-guided procedures require reporting both a surgical/procedural code and a separate radiological supervision and interpretation code to fully capture both the procedural work and the imaging guidance/interpretation work, per the specific code set''s structure and instructional notes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b79cdc0-e674-4348-82e6-381c0319e604', '6d08ddce-67f1-4007-9683-4248b8faa3e7', 2, 'S&I codes replace the need for any procedural code entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba61dea5-0c85-49c7-a4a3-6f6df189abb7', '6d08ddce-67f1-4007-9683-4248b8faa3e7', 3, 'S&I codes are used only for radiation oncology treatment planning');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5eac4388-fb3c-44ac-853c-570677820ac0', 'e4c52755-e49e-4a37-be95-e1204145be42', 0, 'Guidance is never separately coded under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83dae29f-1cb6-4f25-b746-029518d686ec', 'e4c52755-e49e-4a37-be95-e1204145be42', 1, 'Some procedural codes already include imaging guidance within their own descriptor (bundled), while others require separately reporting an appropriate guidance code — reporting a separate guidance code when it''s already bundled into the primary code would overstate the work performed and risk an NCCI edit/compliance issue');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('708f7b4d-bcee-4e31-95d2-855ab711a156', 'e4c52755-e49e-4a37-be95-e1204145be42', 2, 'Guidance coding rules are identical and interchangeable across all CPT sections with no code-specific variation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0864ede8-e353-4e19-be98-d7aa05874c10', 'e4c52755-e49e-4a37-be95-e1204145be42', 3, 'Only ultrasound guidance is ever separately reportable; fluoroscopic guidance is always bundled');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00935f48-2823-4977-9e5d-4daf4f78921a', 'a3495d92-4102-4b34-9868-ee7c575654bd', 0, 'They are identical in purpose and structure to diagnostic imaging codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e9adf12-7911-4653-8927-6c153074878f', 'a3495d92-4102-4b34-9868-ee7c575654bd', 1, 'They capture the distinct workflow of therapeutic radiation treatment — including clinical treatment planning, simulation, dosimetry, device construction, and treatment delivery/management — which is coded very differently from a single diagnostic imaging study');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19ae321b-2f01-41f3-a0eb-43def1eae115', 'a3495d92-4102-4b34-9868-ee7c575654bd', 2, 'Radiation oncology treatment is coded exclusively using unlisted procedure codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79fc4035-36a2-4fe0-a501-05cef8e3c8f4', 'a3495d92-4102-4b34-9868-ee7c575654bd', 3, 'Radiation oncology codes apply only to inpatient hospital settings');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d2473af-a08d-4624-bdb3-ab85c55b7338', 'b7ecc22d-c934-4e8b-9bbc-bf825643bee5', 0, 'It never matters which combination is billed; all combinations are reimbursed identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e391c347-eee2-429d-962c-7d40071dc027', 'b7ecc22d-c934-4e8b-9bbc-bf825643bee5', 1, 'When a single combined code exists that accurately describes the service performed (e.g., a combined abdomen/pelvis CT protocol), reporting the two separate/component codes instead would misrepresent the service and is generally not appropriate when the combined code is the accurate description of what was actually done');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c1f4efa-e1db-432e-b3cd-ce340e429f56', 'b7ecc22d-c934-4e8b-9bbc-bf825643bee5', 2, 'Combined codes are always optional add-ons with no bearing on which base codes should be reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b1472eb-02a2-40c2-9b31-cfde8dca1539', 'b7ecc22d-c934-4e8b-9bbc-bf825643bee5', 3, 'Separate component codes must always be used, and combined codes never exist in CPT');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('228266a4-93e5-4d94-a2d9-85d3d66d3836', 'c9bc9573-55ac-4735-b19a-385abcbb6c13', 0, 'Any single lab test is performed alone, regardless of what other tests were also ordered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1a28b1e-b3f9-4a4b-954e-128fb652183e', 'c9bc9573-55ac-4735-b19a-385abcbb6c13', 1, 'All of the specific individual component tests defined for that named panel are performed, in which case the single panel code is reported rather than reporting each individual component test code separately');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bc22f33-6485-40a2-aaef-0254e13fd5c5', 'c9bc9573-55ac-4735-b19a-385abcbb6c13', 2, 'A physician simply writes the word ''panel'' on the order, regardless of which specific tests were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50143cb6-31df-4709-bde0-bdd1fd617580', 'c9bc9573-55ac-4735-b19a-385abcbb6c13', 3, 'Panels can only be billed in the inpatient setting');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99f2b47c-b1dc-448f-b5f8-6826e8d8bda0', 'f74bda9c-909b-4575-a383-0a44ed1d789c', 0, 'Report the panel code anyway, since most components were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f347b3e-bb7a-48a5-8efe-ae66346ec56d', 'f74bda9c-909b-4575-a383-0a44ed1d789c', 1, 'Report the individual component test codes that were actually performed, since the panel code requires ALL of its defined components to be performed to be correctly reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e9d5f6f-b499-47b5-b64b-48a69f9f95be', 'f74bda9c-909b-4575-a383-0a44ed1d789c', 2, 'Report the panel code and simply subtract one unit of reimbursement manually');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f633abb-de25-41e3-8662-9434897eb41f', 'f74bda9c-909b-4575-a383-0a44ed1d789c', 3, 'Refuse to bill for any of the tests performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cda6d38-9b0b-4d0f-9fd9-164d6807168c', '9f2250d2-4a1b-4e95-bd7f-a362d0651d2b', 0, 'Qualitative tests report a specific numeric measurement/amount, while quantitative tests report only presence/absence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('658ed4f1-1890-424d-9ee8-072868020006', '9f2250d2-4a1b-4e95-bd7f-a362d0651d2b', 1, 'Qualitative tests generally report presence or absence (positive/negative) of a substance, while quantitative tests report a specific numeric measurement/amount of that substance — many lab code descriptors specify which type applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('492b28c7-8e83-40ae-bb0b-5fab16cb0d83', '9f2250d2-4a1b-4e95-bd7f-a362d0651d2b', 2, 'The two terms are fully interchangeable in CPT lab coding with no distinction ever made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6bd49e4-dda7-4a2e-bc78-c2b396843b33', '9f2250d2-4a1b-4e95-bd7f-a362d0651d2b', 3, 'Qualitative and quantitative distinctions apply only to imaging studies, not laboratory tests');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42c0b145-823a-48a8-afec-6e1a10494863', 'bdce3b17-d8db-4686-a1c6-4628fb659587', 0, 'A reflex test is a neurological exam component unrelated to laboratory coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c18329e3-a145-4501-8b2c-40bfd427ce80', 'bdce3b17-d8db-4686-a1c6-4628fb659587', 1, 'A reflex test is an additional, predetermined test automatically performed based on the result of an initial test (e.g., a confirmatory test triggered by an abnormal screening result), and is coded/reported when actually performed based on that triggering result, not automatically for every specimen regardless of the initial result');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6385bd60-d699-41d4-9a8e-993a400c96d5', 'bdce3b17-d8db-4686-a1c6-4628fb659587', 2, 'Reflex testing means repeating the exact same test twice for quality assurance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('691bf96b-e204-4e9c-9f3a-07613c80dd9d', 'bdce3b17-d8db-4686-a1c6-4628fb659587', 3, 'Reflex tests are never separately reportable under any laboratory coding convention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ae1e3dd-83d3-451d-9b5d-d056251d0bd6', '6038e4d3-26e7-41c7-8adc-bfcf7585bda1', 0, 'Levels correspond purely to the physical size of the tissue specimen with no relation to complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f8dc632-1202-4f9d-a571-1a4bc814b025', '6038e4d3-26e7-41c7-8adc-bfcf7585bda1', 1, 'Levels reflect increasing complexity of pathologic examination/diagnostic work required for different specimen types, generally assigned per specimen based on the specific tissue type examined, as defined by the CPT code descriptors'' example lists for each level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1f620a4-42ad-4576-81c9-72d2590ac593', '6038e4d3-26e7-41c7-8adc-bfcf7585bda1', 2, 'All surgical pathology specimens are billed under a single universal code regardless of tissue type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c8dffad-aca8-408a-990b-2aab79259ff6', '6038e4d3-26e7-41c7-8adc-bfcf7585bda1', 3, 'Surgical pathology levels are determined by which hospital department submitted the specimen');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bb738ac-2545-4cff-a047-3a5498bd4958', 'e0d71619-f055-4e44-9641-670de8b46f17', 0, 'Only one unit of the surgical pathology code may ever be reported regardless of how many distinct specimens were submitted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36ecdbd3-4b99-4533-a4d7-6206ff9e13aa', 'e0d71619-f055-4e44-9641-670de8b46f17', 1, 'Each distinct specimen is generally reported and coded separately (at its own appropriate complexity level, if levels differ), reflecting the actual number of specimens examined, not automatically consolidated into a single unit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61af0465-531c-4cb7-a96d-8a0657fa8d1f', 'e0d71619-f055-4e44-9641-670de8b46f17', 2, 'Multiple specimens are always billed as a single combined ''panel'' code, similar to laboratory panels');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03224800-ffad-4315-88f8-cf32cad4f357', 'e0d71619-f055-4e44-9641-670de8b46f17', 3, 'Additional specimens beyond the first are never separately reportable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59b83809-8c9f-4877-9a71-cb4430abff6d', 'a5b7173d-a173-4ef7-b6c0-115b50547f89', 0, 'They are used for tests analyzing DNA/RNA-level genetic/genomic information (e.g., specific gene mutation analysis), structured very differently (often per-gene or per-analyte) than traditional chemistry panel codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cce773f9-2a9d-4bc3-80a0-fb49468571ed', 'a5b7173d-a173-4ef7-b6c0-115b50547f89', 1, 'They are simply another name for basic metabolic panel codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c0500d6-af80-4a89-b63f-bc1d026c4a98', 'a5b7173d-a173-4ef7-b6c0-115b50547f89', 2, 'Molecular pathology codes apply only to blood type testing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a009653-c659-4348-a839-285476910c42', 'a5b7173d-a173-4ef7-b6c0-115b50547f89', 3, 'Molecular pathology and routine chemistry codes are billed identically with no structural distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26411de3-19ba-4da0-98bf-3cafca90dd1c', '178e1c7c-71d9-49da-80ea-13c6658cab35', 0, 'This distinction never affects coding or billing in any way');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4087ba3-1775-474b-981c-aa7097b1cfb6', '178e1c7c-71d9-49da-80ea-13c6658cab35', 1, 'It affects which entity bills for the test (and potentially requires modifier 90 ''reference laboratory'' when a physician bills for a test actually performed by an outside lab), since correct billing should reflect who actually performed the test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5853fc6-2bc7-4184-ba04-a8b740c5fced', '178e1c7c-71d9-49da-80ea-13c6658cab35', 2, 'Reference lab tests can never be billed by anyone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76bcedec-c59f-4de8-a272-c5acfcab38ce', '178e1c7c-71d9-49da-80ea-13c6658cab35', 3, 'In-house lab tests always require a pathologist''s separate professional interpretation code regardless of test type');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccf7c4f3-8bff-4b91-b7cd-c5f388bfe34c', 'c33a44e9-c7c2-4dab-8f15-9395a5e0dd8e', 0, 'The original inadequate test is still billed in full as if a complete, valid result were obtained');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fbb73bc-404c-4b81-b7da-41ea0bfcd3d5', 'c33a44e9-c7c2-4dab-8f15-9395a5e0dd8e', 1, 'Coding/billing should reflect the actual work performed and the validity of the result — an unsatisfactory specimen that couldn''t be meaningfully interpreted is a documentation and billing-accuracy issue distinct from a genuine, successfully completed repeat test (which modifier 91 would address), and payer-specific policy generally governs whether/how the original attempt may be billed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85968cef-2af9-4d62-a895-9aa25f68d49e', 'c33a44e9-c7c2-4dab-8f15-9395a5e0dd8e', 2, 'Inadequate specimens are always billed exactly the same as a completed, valid test with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9f3c386-d3a0-494d-b7ba-ebe5ca750f2e', 'c33a44e9-c7c2-4dab-8f15-9395a5e0dd8e', 3, 'The patient is always billed twice regardless of what actually occurred clinically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a002568a-0126-42cd-9de4-1cb89c1da2b8', '599ecae5-a9b7-41ad-a6ab-04b727cc76b1', 0, 'They are coded identically with no distinction ever made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35b985e3-4eac-4ead-927d-34631ca9fd73', '599ecae5-a9b7-41ad-a6ab-04b727cc76b1', 1, 'Pathology consultation codes exist specifically for a pathologist reviewing and rendering an opinion on material (slides, blocks) originally examined/prepared by another party — a structurally distinct service from the pathologist who performed the original, primary examination and diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8625f959-2c1b-4f17-bf64-8486ce37ae03', '599ecae5-a9b7-41ad-a6ab-04b727cc76b1', 2, 'Pathology consultations are never separately billable under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6027d8f-7e2c-4533-90e7-73043399e0b1', '599ecae5-a9b7-41ad-a6ab-04b727cc76b1', 3, 'Consultation codes in pathology apply only to molecular genetic testing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18eb7a9e-8150-4508-9c12-999a77655cb9', '69a61214-bf8e-4db9-8474-7a5d95ff162c', 0, 'A single code covers both the vaccine product and its administration together, with no distinction ever made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27670894-c2b2-4b22-8f85-5bbd15fea10a', '69a61214-bf8e-4db9-8474-7a5d95ff162c', 1, 'Two separate code components are generally involved: a code for the vaccine/toxoid product itself, and a separate code for the administration service (the act of giving the injection/counseling), both of which may be reported together for the same encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea56bb44-dab2-4340-9559-bace5e1d21db', '69a61214-bf8e-4db9-8474-7a5d95ff162c', 2, 'Only the administration code is ever reported; the vaccine product is never separately coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9601dc40-8244-45a6-aad3-4090a04e7c49', '69a61214-bf8e-4db9-8474-7a5d95ff162c', 3, 'Vaccine coding applies only to pediatric patients, never adults');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc143d8b-331c-4cc1-a0f0-9099f6fe8ea7', 'b90211e5-55b4-4e74-9d9d-a58d1475a6ba', 0, 'All rehabilitation codes are billed as a single flat visit fee with no time component ever considered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f107731-db28-4f66-adf1-b9aeac8ef19a', 'b90211e5-55b4-4e74-9d9d-a58d1475a6ba', 1, 'Certain rehabilitation procedures are coded per defined time increments (e.g., per 15-minute unit of direct one-on-one patient contact), requiring accurate time documentation to support the number of units reported, while other services are reported once per encounter regardless of time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9bf04db-baff-4ac7-8c95-ef4a065f9423', 'b90211e5-55b4-4e74-9d9d-a58d1475a6ba', 2, 'Time-based coding applies only to surgical procedures, never therapy services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ecf499c-158a-4904-b3cb-8a21d7cbd75c', 'b90211e5-55b4-4e74-9d9d-a58d1475a6ba', 3, 'Untimed codes may be billed multiple times per encounter to reflect additional time spent, identically to timed codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa45d66c-b557-4ef1-8972-3d9fb429d863', 'fc192365-78f4-4485-849c-de56e1106daa', 0, 'They are the exact same code family used interchangeably for any type of mental health encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d33d047f-aaa6-48c7-92b6-1460cae6d3e9', 'fc192365-78f4-4485-849c-de56e1106daa', 1, 'A psychiatric diagnostic evaluation code is used for the initial (or periodic re-)assessment/evaluation encounter, while psychotherapy codes (often selected/leveled by time) are used for ongoing therapeutic treatment sessions — these represent structurally distinct service types within the Medicine section');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f01e48c0-8f03-41d1-a833-e2c12ab48345', 'fc192365-78f4-4485-849c-de56e1106daa', 2, 'Psychotherapy is coded using E/M codes exclusively, with no distinct Medicine-section codes existing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91ef3477-d40e-45e5-87f7-d23a3fa7367d', 'fc192365-78f4-4485-849c-de56e1106daa', 3, 'Diagnostic evaluation codes can only be reported by psychologists, never psychiatrists');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0085db70-820f-47bf-83fe-d2a260ce0ce3', 'ef6a77cb-5fe4-4b15-9f08-a499ab970d06', 0, 'Psychotherapy can never be reported on the same date as an E/M service under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b88243b4-8a07-4b8e-9c21-e191f655b364', 'ef6a77cb-5fe4-4b15-9f08-a499ab970d06', 1, 'Certain psychotherapy codes are structured as add-on codes specifically intended to be reported together with an E/M service provided on the same date, reflecting a combined medication-management-plus-therapy encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9526016f-e752-457e-9ee2-182acdd4d1ad', 'ef6a77cb-5fe4-4b15-9f08-a499ab970d06', 2, 'E/M and psychotherapy must always be billed as two completely separate encounters on different dates');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1296b988-c7c4-4048-a28f-b727b9e608fa', 'ef6a77cb-5fe4-4b15-9f08-a499ab970d06', 3, 'Add-on psychotherapy codes replace the need for any E/M code entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('079e5c7f-b0b5-4fd4-b548-ebc746bd4e6f', '8d1ded90-6255-4711-9a00-2d4e4b4d9932', 0, 'A single code always captures every possible component (supervision, tracing, interpretation) with no separate professional/technical component ever applicable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b64a09c-ca13-4c33-84e7-8b95128b2286', '8d1ded90-6255-4711-9a00-2d4e4b4d9932', 1, 'Depending on the specific code and circumstances, cardiovascular stress testing may involve separately identifiable components (e.g., physician supervision/interpretation vs. technical performance) similar in concept to the professional/technical split seen elsewhere in CPT, governed by the specific code descriptor and modifier conventions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e70e984f-8a0b-4359-99e7-5c2a44371f56', '8d1ded90-6255-4711-9a00-2d4e4b4d9932', 2, 'Stress tests are coded exclusively using unlisted procedure codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c26c694c-dbe8-48cb-be77-e6786904620f', '8d1ded90-6255-4711-9a00-2d4e4b4d9932', 3, 'Cardiovascular stress testing is coded identically to a routine ECG regardless of the additional stress-testing components involved');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f9dde70-b81c-48d1-8db5-10654f54e6dc', 'da0d1800-7c31-4ff0-b5ae-a979f959d92b', 0, 'They describe major surgical procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4905bed3-6cd6-44fb-b581-a146471a3afe', 'da0d1800-7c31-4ff0-b5ae-a979f959d92b', 1, 'They capture ancillary circumstances or services related to the primary service being provided (e.g., an after-hours office visit surcharge concept, or specimen handling/transport), reported in addition to the primary service code, not as a stand-alone primary procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('442a747a-41fd-45a4-bed9-76309f796171', 'da0d1800-7c31-4ff0-b5ae-a979f959d92b', 2, 'They are used only for telehealth-specific services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34115837-1408-4990-b9ef-a73c8e13d828', 'da0d1800-7c31-4ff0-b5ae-a979f959d92b', 3, 'They replace the need for reporting the primary E/M or procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e17acd18-af07-4841-b3aa-9bfdb8cd6f0a', 'dbd710dd-c8d5-4404-b8f4-eef97ae81447', 0, 'An E/M code must always be reported regardless of whether a separate E/M service was actually provided');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('74319ff8-206b-4eff-aedf-9d509655b7a4', 'dbd710dd-c8d5-4404-b8f4-eef97ae81447', 1, 'The vaccine product and administration codes may be reported on their own, without an accompanying E/M code, when no separately identifiable E/M service was performed that day');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f60fa1f-63bd-4631-bdad-f32667ff83dc', 'dbd710dd-c8d5-4404-b8f4-eef97ae81447', 2, 'Immunizations can never be billed without an accompanying E/M visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9011afcf-b6d8-4a32-847a-6059b2456bfb', 'dbd710dd-c8d5-4404-b8f4-eef97ae81447', 3, 'Only the administration code may be reported; the vaccine product must always be billed separately by the pharmacy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19662833-2ff1-4c45-8c49-c2627c3992cd', '87bf79d0-893e-4b3e-95d9-15402eedef23', 0, 'They capture non-face-to-face care coordination/management time for patients with multiple chronic conditions, generally requiring specific time thresholds and documented care-plan activities, distinct from a traditional face-to-face E/M visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10923eec-80fd-4b86-89e8-8a162f465e11', '87bf79d0-893e-4b3e-95d9-15402eedef23', 1, 'They apply only to a single face-to-face annual visit with no ongoing time component');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('193c140a-1fd1-4f24-920b-a58c6e980d77', '87bf79d0-893e-4b3e-95d9-15402eedef23', 2, 'Care management codes replace the need for any E/M coding for chronic disease patients entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('058abef4-9b38-4562-b4ed-a52d65e9f3e4', '87bf79d0-893e-4b3e-95d9-15402eedef23', 3, 'They are billed identically to a routine office visit with no time-tracking requirement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32535b72-f2f4-4b6a-87ee-9f10eaf66fd2', 'de9c8c2d-9e9b-4d93-9f98-d960c230eaa3', 0, 'They are the same code family with no distinction between testing and treatment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4596a50e-5835-4747-960a-ec2397ed8c67', 'de9c8c2d-9e9b-4d93-9f98-d960c230eaa3', 1, 'Allergy testing (identifying specific allergen sensitivities) and allergen immunotherapy (ongoing treatment via allergen extract administration) are distinct code families representing different clinical services performed at different points in a patient''s allergy care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dfc8cd2-30d6-4b20-8a1e-2afcc98544e1', 'de9c8c2d-9e9b-4d93-9f98-d960c230eaa3', 2, 'Allergy testing is coded using Surgery-section codes exclusively');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a772b2d2-8cf6-470f-a7ac-ce174e28a0e1', 'de9c8c2d-9e9b-4d93-9f98-d960c230eaa3', 3, 'Immunotherapy administration is coded identically to a routine vaccine administration code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4395c7cf-7076-4555-8401-1237de78b0f4', '4b48080b-19c5-47c2-8cc5-adb8df9d7555', 0, 'Only one combined code ever covers both the extract and its administration, with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f9eed3f-5dac-4fed-96fb-88ec9ec8fdb7', '4b48080b-19c5-47c2-8cc5-adb8df9d7555', 1, 'CPT structure allows for separately reporting the preparation/provision of the antigen (extract) and the actual injection administration service, since these represent distinct components of the overall immunotherapy service, similar in concept to the vaccine product/administration split discussed earlier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85ebeffb-c29c-454f-86f2-8c2cf7a7a99c', '4b48080b-19c5-47c2-8cc5-adb8df9d7555', 2, 'The extract is always supplied free of charge and never separately billable under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8da4a82-eb29-41b4-8217-86c1573a29ac', '4b48080b-19c5-47c2-8cc5-adb8df9d7555', 3, 'Administration codes for immunotherapy are billed only once per calendar year regardless of visit frequency');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1d4c126-2bf4-4e20-a84d-65c195699e0e', 'e7dbb161-cd2a-4bda-9fcc-a1fd80dfb6f6', 0, 'Increase reimbursement for facilities that report more codes per claim');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f87c250f-1150-49fa-ac7d-93d445aa6820', 'e7dbb161-cd2a-4bda-9fcc-a1fd80dfb6f6', 1, 'Prevent improper payment when two codes that should not be reported together for the same patient on the same date of service (due to one being a component of the other, or being mutually exclusive) are billed together, absent an appropriate modifier indicating genuine clinical distinctness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc13d0bb-b7ef-42f7-bc38-99972c9bb413', 'e7dbb161-cd2a-4bda-9fcc-a1fd80dfb6f6', 2, 'Determine which specialty may treat a given diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5cd156ff-0510-463c-8a6f-208a6c45b47e', 'e7dbb161-cd2a-4bda-9fcc-a1fd80dfb6f6', 3, 'Apply only to inpatient hospital claims, never physician/professional claims');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a94db366-5ea0-4154-adb0-076b33fc73a4', '02fb6d58-7acd-4f3f-a8b0-fe0f1a973073', 0, 'A limit on the maximum units of a specific HCPCS/CPT code that would be clinically plausible for a single patient on a single date of service, flagging claims that exceed that threshold for review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c32ce14-4904-43a4-a7e6-d8339d9c6dcf', '02fb6d58-7acd-4f3f-a8b0-fe0f1a973073', 1, 'A rule preventing any code from ever being billed more than once in a patient''s lifetime');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5cf8e6ab-6bcf-4739-a693-46808ddec166', '02fb6d58-7acd-4f3f-a8b0-fe0f1a973073', 2, 'An edit that applies only to laboratory codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('796d019f-8be4-4c7d-a685-88a044a657ca', '02fb6d58-7acd-4f3f-a8b0-fe0f1a973073', 3, 'A requirement that every procedure code have an identical MUE value');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7575cc2d-58c5-48ba-a68f-001ad7344deb', '7dce2333-5763-4fc7-96e2-bad0c4dc5dbf', 0, 'The edit can always be bypassed using any modifier the coder chooses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe6ae110-23e4-4233-b996-d4a468174025', '7dce2333-5763-4fc7-96e2-bad0c4dc5dbf', 1, 'A modifier indicator of 0 means no modifier may be used to bypass the edit under any circumstance — the two codes simply cannot both be paid for the same patient on the same date, regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2d037e5-ea87-4d29-b8e9-5afc494c9dc4', '7dce2333-5763-4fc7-96e2-bad0c4dc5dbf', 2, 'A modifier indicator of 0 means the edit doesn''t actually apply to that code pair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be17d83e-c575-4961-8281-4a0aedb8a98b', '7dce2333-5763-4fc7-96e2-bad0c4dc5dbf', 3, 'A modifier indicator of 0 applies only to bilateral procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('046bd756-3577-4e94-b063-ed789941407b', 'abee760e-b68f-42b2-a19c-02cc1a6f0ef4', 0, 'Applying the modifier automatically to every denied claim regardless of clinical circumstances, purely to get paid');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c91fd678-b927-4c23-87cb-669d3db50547', 'abee760e-b68f-42b2-a19c-02cc1a6f0ef4', 1, 'Applying the modifier (e.g., 59 or an X{EPSU} modifier) only when the clinical documentation genuinely supports that the two services were distinct (different session, site, or separate/independent procedure) — not as a default workaround for denied claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93d4aad0-ec68-477a-b600-5f405dd7a528', 'abee760e-b68f-42b2-a19c-02cc1a6f0ef4', 2, 'Modifier indicator ''1'' edits can never actually be bypassed despite the indicator');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8772037b-358a-4f68-a025-2f9f3b06a50f', 'abee760e-b68f-42b2-a19c-02cc1a6f0ef4', 3, 'Only physicians, never coders, may ever apply a bypass modifier');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('131b4a52-7bff-45d5-a90f-b0530023a9ff', '67ea3df5-b4e4-4989-a00c-1d446d296713', 0, 'Add-on codes have no special NCCI-related edit considerations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('297a8bf6-4184-40d6-9277-fe57b3114f1a', '67ea3df5-b4e4-4989-a00c-1d446d296713', 1, 'Add-on codes are edited to ensure they are reported only alongside an appropriate, eligible primary procedure code specified for that add-on — reporting an add-on code without its required primary code present would be inconsistent with CPT''s own add-on code convention and generally rejected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97bdaf2d-3140-47a4-a7cb-3c1a58a1969a', '67ea3df5-b4e4-4989-a00c-1d446d296713', 2, 'Add-on codes are always primary codes that require their own separate add-on code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7538d4d5-2144-4ea5-83fd-45dcf2001ce1', '67ea3df5-b4e4-4989-a00c-1d446d296713', 3, 'NCCI edits apply only to non-add-on codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0d68399-5944-48f6-90c2-d02651a4d508', 'dd08f724-560e-451e-96c2-2b223155f0f4', 0, 'NCCI edits have no compliance relevance; they are purely a payment-processing technicality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48a42f95-7666-444b-babe-79a6a5ffbbd3', 'dd08f724-560e-451e-96c2-2b223155f0f4', 1, 'Systematically overriding NCCI edits with modifiers not clinically supported by documentation (to force payment of code combinations that shouldn''t be billed together) can create real fraud/abuse exposure, similar to other improper-coding compliance risks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbfac2d6-9756-4df9-bac7-e7cc19b0e9f8', 'dd08f724-560e-451e-96c2-2b223155f0f4', 2, 'NCCI edits apply only to Medicaid, never Medicare or commercial payers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d05f2f46-ef32-4888-9d4b-3ef3fa5a0b2b', 'dd08f724-560e-451e-96c2-2b223155f0f4', 3, 'Coders have no role in NCCI compliance; it is solely a billing-department system configuration issue');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02e37fdb-dcc0-4a04-a1ba-62097ab296ac', '2f32be9e-a60f-4d5c-8947-1a13b3912e3c', 0, 'Used when a lab test is repeated on the same day for the same patient to obtain a new, medically necessary result reflecting a change in the patient''s condition (e.g., a repeat glucose level to monitor treatment response), not simply to confirm an initial result or due to testing/equipment failure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8051d92-8008-4394-8f99-2c00ff40e0a6', '2f32be9e-a60f-4d5c-8947-1a13b3912e3c', 1, 'Used to indicate a lab test was sent to an outside reference laboratory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5ed69f7-81b9-48a4-9624-3bc32d087b78', '2f32be9e-a60f-4d5c-8947-1a13b3912e3c', 2, 'Used interchangeably with modifier 76 (repeat procedure by same physician) for any type of repeated service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2abce939-a946-4447-a29a-ab0c9a210106', '2f32be9e-a60f-4d5c-8947-1a13b3912e3c', 3, 'Used only for anatomic pathology specimens, never chemistry tests');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dfd9d79-2af4-4c18-9bb0-736a84c4c629', '285453ba-dfa7-48eb-84e9-1cc1195ea0b2', 0, 'Used when the identical procedure is repeated by the same physician on the same day, to indicate the repetition was a distinct, medically necessary event rather than a duplicate/erroneous claim line');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4aeb65b5-06f9-48fb-8409-bab8fe199805', '285453ba-dfa7-48eb-84e9-1cc1195ea0b2', 1, 'Used only for laboratory tests, never procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ddf1626-1b7a-4ddd-88fb-5e043b14f9e5', '285453ba-dfa7-48eb-84e9-1cc1195ea0b2', 2, 'Used exclusively when two different physicians each perform the same procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c03d5e95-5cfd-47ee-b906-4d88284d9e31', '285453ba-dfa7-48eb-84e9-1cc1195ea0b2', 3, 'Used to indicate a procedure was performed at a different facility');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('461eb197-685a-45d2-aff2-ae4193bdcd97', 'c62c58f9-d583-40ec-b620-70c712d7f2f1', 0, 'HCPCS Level II codes replace CPT codes entirely for all services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81010a10-b437-47ac-8654-3015cc0e28fc', 'c62c58f9-d583-40ec-b620-70c712d7f2f1', 1, 'HCPCS Level II codes supplement CPT by covering items/services not included in CPT — notably durable medical equipment, certain drugs/biologicals, and other supplies — using an alphanumeric structure distinct from CPT''s numeric structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d45ed21a-1d9e-4fda-bf72-b12d8fed94a5', 'c62c58f9-d583-40ec-b620-70c712d7f2f1', 2, 'HCPCS Level II applies only to dental procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('766b8240-dfa2-49fb-8f2a-ac8127e37004', 'c62c58f9-d583-40ec-b620-70c712d7f2f1', 3, 'CPT and HCPCS Level II are simply two different names for the exact same code set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc9a51f8-cd29-41bc-bd64-90eff84e08ef', '65ca08ed-56e9-4033-9f09-c6b343527108', 0, 'Automatically resubmitting with a bypass modifier regardless of documentation, since the system flagged it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88a8dff0-c834-4c04-a8af-146e3895bb32', '65ca08ed-56e9-4033-9f09-c6b343527108', 1, 'Reviewing the underlying clinical documentation to determine whether the flagged code combination/unit count is actually accurate and appropriately supported (potentially warranting a compliant modifier), or whether the original coding needs correction — not reflexively overriding the system flag either way without review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b5d9df4-4c33-440b-921b-79f21eaf259b', '65ca08ed-56e9-4033-9f09-c6b343527108', 2, 'Ignoring all system flags as false positives by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ee0f9e7-ad56-43ac-bbd5-5e3abdb3dc4d', '65ca08ed-56e9-4033-9f09-c6b343527108', 3, 'Deleting one of the flagged codes at random to clear the edit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
